    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_gold_gray.png'; Binary = $true; Allowed = @('F60901B9F58C64C43055D92BD9E0E029D7DA74781668E1C607FEDB01B7E9D223'); MayCreate = $true; After = '5E703A5F8A4BE6D0F97D4273FD18066C288557336F7E8D7E4270B040B78904A8'; PayloadHash = '5E703A5F8A4BE6D0F97D4273FD18066C288557336F7E8D7E4270B040B78904A8'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_gold_white.png'; Binary = $true; Allowed = @('AB30536819A83558B772421275D33BA8301DAB83D8A503D8F2773A17B2B99F3F'); MayCreate = $true; After = '6924F70B7D686D6FDB26324BB016EB08F4662B085E7EF11558E21FD80E7274AC'; PayloadHash = '6924F70B7D686D6FDB26324BB016EB08F4662B085E7EF11558E21FD80E7274AC'; Data = '' },
