    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_pink_white.png'; Binary = $true; Allowed = @('9877F2A236189218EA72C90317DAC1E871662CEC96BE7B4936FD72A006CB8F78'); MayCreate = $true; After = 'A27C681813E1764708C15F5831ACEA264A8A4F67DE6EA347C69421A3D611A0C6'; PayloadHash = 'A27C681813E1764708C15F5831ACEA264A8A4F67DE6EA347C69421A3D611A0C6'; Data = '' },
